document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("stats-grid");e&&(e.innerHTML=ZERO_INFO.quickStats.map(e=>`\n                <div class="stat-pill">\n                    <span class="stat-icon">${e.icon}</span>\n                    <span class="stat-value">${e.value}</span>\n                    <span class="stat-label">${e.label}</span>\n                </div>\n            `).join(""));const t=document.getElementById("history-content");t&&(t.innerHTML=`\n            <h3>${HISTORY_TEXT.title}</h3>\n            ${HISTORY_TEXT.paragraphs.map(e=>`<p>${e}</p>`).join("")}\n        `);const n=document.getElementById("timeline-list");n&&(n.innerHTML=TIMELINE.map(e=>`\n                <div class="timeline-item">\n                    <div class="timeline-era">${e.era}</div>\n                    <div class="timeline-body">\n                        <h4>${e.title}</h4>\n                        <p>${e.description}</p>\n                    </div>\n                </div>\n            `).join(""));const i=document.getElementById("number-line-desc");i&&(i.textContent=NUMBER_LINE_INFO.description);const s=document.getElementById("comparison-body");s&&(s.innerHTML=COMPARISON_ROWS.map(e=>`\n                <tr>\n                    <td>${e.aspect}</td>\n                    <td>${e.before}</td>\n                    <td>${e.after}</td>\n                </tr>\n            `).join(""));const o=document.getElementById("applications-grid");o&&(o.innerHTML=APPLICATIONS.map(e=>`\n                <div class="principle-card">\n                    <h4>${e.title}</h4>\n                    <p>${e.description}</p>\n                </div>\n            `).join(""));const a=document.getElementById("references-list");a&&(a.innerHTML=REFERENCES.map(e=>`<li><a href="${e.link}" target="_blank" rel="noopener">${e.text}</a></li>`).join(""));const l=document.getElementById("number-line-slider"),d=document.getElementById("number-line-marker"),r=document.getElementById("number-line-value"),c=document.getElementById("number-line-fact");function m(e){const t=(e- -10)/20*100;d.style.left=`${t}%`,d.textContent=String(e),r.textContent=String(e),c.textContent=function(e){return 0===e?"Zero — the anchor point. Neither positive nor negative.":e>0?`${e} is ${e} step${1===e?"":"s"} to the right of zero (positive).`:`${e} is ${Math.abs(e)} step${1===Math.abs(e)?"":"s"} to the left of zero (negative).`}(e),d.classList.toggle("is-zero",0===e)}l&&d&&(l.addEventListener("input",e=>{m(Number(e.target.value))}),m(0))});